/*
 * Linux platform glue (i386 and armhf). The GBA address space comes from
 * port/android/native/port_memory_android.c (POSIX mmap at the hardware
 * addresses); this file provides the game sections, Shift-JIS conversion
 * and the crash log.
 */
#define _GNU_SOURCE
#include <SDL3/SDL.h>
#include <execinfo.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

#include "port/port.h"
#include "linux_sjis.h" /* generated by port/tools/build_linux.py */

extern char __start_khdata[], __stop_khdata[], __start_khbss[], __stop_khbss[];

void PortGameSections(char** data, size_t* size, char** bss, size_t* bsize) {
    *data = __start_khdata;
    *size = (size_t)(__stop_khdata - __start_khdata);
    *bss = __start_khbss;
    *bsize = (size_t)(__stop_khbss - __start_khbss);
}

/* gLinuxSjis is sorted by Shift-JIS code: binary search one way, a scan the
   other (only used for the few strings typed into menus). */
unsigned PortSjisToCodepoint(unsigned code) {
    int lo = 0, hi = (int)(sizeof(gLinuxSjis) / sizeof(gLinuxSjis[0]));

    while (lo < hi) {
        int m = (lo + hi) / 2;
        if (gLinuxSjis[m][0] < code)
            lo = m + 1;
        else
            hi = m;
    }
    return lo < (int)(sizeof(gLinuxSjis) / sizeof(gLinuxSjis[0])) && gLinuxSjis[lo][0] == code ? gLinuxSjis[lo][1] : 0;
}

int PortCodepointToSjis(unsigned cp) {
    size_t i;

    if (cp < 128)
        return (int)cp;
    for (i = 0; i < sizeof(gLinuxSjis) / sizeof(gLinuxSjis[0]); i++)
        if (gLinuxSjis[i][1] == cp)
            return (int)gLinuxSjis[i][0];
    return 0;
}

void PortWatchdogStart(void) {}

#ifdef __arm__
/* ARM: the known NULL reads go through BIOS_PTR (as on Android) and the
   division helpers return 0 for a zero divisor, like the GBA's libgcc. */
void PortBiosFaultInstall(void) {
    PortLog("Linux ARM: BIOS_PTR helpers; no fault recovery");
}
int __aeabi_idiv0(int value) {
    (void)value;
    return 0;
}
long long __aeabi_ldiv0(long long value) {
    (void)value;
    return 0;
}
#endif

static void CrashSignal(int sig) {
    void* frames[32];
    int n = backtrace(frames, 32);
    FILE* f = fopen(PortConfigPath("kh_com.log"), "a");

    if (f != NULL) {
        fprintf(f, "CRASH: signal %d\n", sig);
        fflush(f);
        backtrace_symbols_fd(frames, n, fileno(f));
        fclose(f);
    }
    signal(sig, SIG_DFL);
    raise(sig);
}

/* Installed before the BIOS fault handler, which chains here for faults it
   does not emulate. */
void PortCrashHandlerInstall(void) {
    signal(SIGSEGV, CrashSignal);
    signal(SIGBUS, CrashSignal);
    signal(SIGILL, CrashSignal);
    signal(SIGFPE, CrashSignal);
}
